<?php

namespace Agent\AgentBundle\Repository;

/**
 * ClasseRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class DocumentRepository extends \Doctrine\ORM\EntityRepository
{
     public function afficherDocumentAgent ($matricule) {
        $qb =$this->createQueryBuilder('d')
                ->where("d.Matricule = :Matricule")
                ->setParameter("Matricule", $matricule);
                
                return $qb->getQuery()->getResult();
               
    }

    public function afficherDocumentNote($matricule) {
    	$libelle="Note d\'Affectation";
        $qb =$this->createQueryBuilder('d')
                ->where("d.Matricule = :Matricule and d.libelle = :libelle")
                ->setParameter("Matricule", $matricule)
                ->setParameter("Matricule", $libelle);     
                return $qb->getQuery()->getOneorNullResult();
               
    }
}
